[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
<style>
:root {
  --black: #000000;
  --purple: #7638FA;
  --orange: #FF7A00;
  --purple-light: #f3eeff;
  --orange-light: #fff7f0;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --white: #ffffff;
  --radius-sm: 0.5rem;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-2xl: 2rem;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --max-width: 1200px;
  --header-height: 4rem;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--white);
  color: var(--gray-900);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ── Header ── */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
}

.header-inner {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 800;
  font-size: 1.375rem;
  letter-spacing: -0.02em;
  color: var(--black);
}

.logo-icon {
  width: 2.25rem;
  height: 2.25rem;
  background: linear-gradient(135deg, var(--purple), var(--orange));
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: color 0.15s ease;
  letter-spacing: -0.01em;
}

.nav-links a:hover {
  color: var(--black);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.btn-login {
  padding: 0.5rem 1.25rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--white);
  background: var(--black);
  transition: all 0.15s ease;
  letter-spacing: -0.01em;
}

.btn-login:hover {
  background: var(--gray-800);
  transform: translateY(-1px);
}

.hamburger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius);
  color: var(--black);
  transition: background 0.15s ease;
}

.hamburger:hover {
  background: var(--gray-100);
}

/* Mobile menu overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  top: var(--header-height);
  background: var(--white);
  z-index: 999;
  display: flex;
  flex-direction: column;
  padding: 2rem 1.5rem;
  gap: 0.5rem;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow-y: auto;
}

.mobile-menu.open {
  transform: translateX(0);
}

.mobile-menu a {
  padding: 1rem;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--gray-800);
  border-radius: var(--radius);
  transition: background 0.15s ease;
  letter-spacing: -0.01em;
}

.mobile-menu a:hover {
  background: var(--gray-100);
}

/* ── Hero ── */
.hero {
  padding: calc(var(--header-height) + 3rem) 1.5rem 4rem;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #faf5ff 0%, #fff7f0 50%, #fef3ff 100%);
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(118,56,250,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(255,122,0,0.06) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 2rem;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 1rem;
  border-radius: 9999px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--gray-700);
  letter-spacing: -0.01em;
}

.hero-badge-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--purple), var(--orange));
  animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.3); }
}

.hero h1 {
  font-size: clamp(2.25rem, 5vw, 4rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--black);
  max-width: 800px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--purple), var(--orange));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--gray-600);
  max-width: 560px;
  line-height: 1.7;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  border-radius: 9999px;
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  background: linear-gradient(135deg, var(--purple), #c44dff);
  transition: all 0.2s ease;
  letter-spacing: -0.01em;
  box-shadow: 0 4px 24px rgba(118,56,250,0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(118,56,250,0.4);
}

.btn-primary:active {
  transform: translateY(0);
}

.hero-visual {
  width: 100%;
  max-width: 700px;
  height: 280px;
  background: linear-gradient(135deg, rgba(118,56,250,0.15), rgba(255,122,0,0.15));
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero-visual-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  padding: 1rem;
  width: 90%;
}

.hero-visual-tile {
  aspect-ratio: 1;
  border-radius: var(--radius);
  background: var(--white);
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

/* ── Section Shared ── */
.section {
  padding: 5rem 1.5rem;
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--purple);
  margin-bottom: 1rem;
}

.section-headline {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--black);
  margin-bottom: 1rem;
}

.section-description {
  font-size: 1.0625rem;
  color: var(--gray-600);
  line-height: 1.7;
  max-width: 600px;
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--black);
  transition: gap 0.2s ease;
  letter-spacing: -0.01em;
}

.section-link:hover {
  gap: 0.625rem;
}

.section-link i {
  width: 1.125rem;
  height: 1.125rem;
}

/* ── Features ── */
.features-section {
  background: var(--white);
}

.features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 3rem;
}

.feature-card {
  padding: 2rem;
  border-radius: var(--radius-xl);
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  transition: all 0.2s ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  border-color: var(--purple);
  box-shadow: 0 8px 32px rgba(118,56,250,0.08);
}

.feature-card-icon {
  width: 3rem;
  height: 3rem;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.5rem;
}

.feature-card:nth-child(1) .feature-card-icon { background: #f3eeff; color: var(--purple); }
.feature-card:nth-child(2) .feature-card-icon { background: #fff0e5; color: var(--orange); }
.feature-card:nth-child(3) .feature-card-icon { background: #fee2f8; color: #c026d3; }
.feature-card:nth-child(4) .feature-card-icon { background: #e0f2fe; color: #0284c7; }

.feature-card h3 {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--black);
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.6;
}

/* ── Safety ── */
.safety-section {
  background: linear-gradient(180deg, #faf5ff 0%, var(--white) 100%);
  border-top: 1px solid #f3eeff;
  border-bottom: 1px solid #f3eeff;
}

.safety-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
  align-items: center;
}

.safety-visual {
  background: linear-gradient(135deg, #f3eeff, #fdf2ff);
  border-radius: var(--radius-2xl);
  padding: 2rem;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.safety-stat {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  text-align: center;
  box-shadow: 0 2px 12px rgba(0,0,0,0.04);
}

.safety-stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--purple);
  letter-spacing: -0.02em;
}

.safety-stat-label {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-top: 0.25rem;
}

/* ── Creators ── */
.creators-section {
  background: var(--white);
}

.creators-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
  align-items: center;
}

.creators-visual {
  height: 320px;
  background: linear-gradient(135deg, #fff7f0, #fff0e5, #fef3ff);
  border-radius: var(--radius-2xl);
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.creators-spotlight {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--purple), var(--orange));
  opacity: 0.15;
  filter: blur(40px);
  position: absolute;
}

.creators-icon-row {
  display: flex;
  gap: 1rem;
  position: relative;
  z-index: 1;
}

.creators-icon-circle {
  width: 4rem;
  height: 4rem;
  border-radius: 50%;
  background: var(--white);
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

/* ── Tagline Banner ── */
.tagline-banner {
  padding: 4rem 1.5rem;
  background: linear-gradient(135deg, var(--purple), #9b5cf6, #c44dff);
  position: relative;
  overflow: hidden;
}

.tagline-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.tagline-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  position: relative;
  z-index: 1;
}

.tagline-text {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
  line-height: 1.3;
}

/* ── News ── */
.news-section {
  background: var(--white);
  overflow: hidden;
}

.news-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.news-link {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--purple);
  white-space: nowrap;
  transition: gap 0.2s ease;
  letter-spacing: -0.01em;
}

.news-link:hover {
  gap: 0.625rem;
}

.news-carousel {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 0.5rem;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.news-carousel::-webkit-scrollbar {
  display: none;
}

.news-card {
  min-width: 300px;
  max-width: 380px;
  flex-shrink: 0;
  scroll-snap-align: start;
  border-radius: var(--radius-xl);
  background: var(--white);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: all 0.2s ease;
  cursor: pointer;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  border-color: var(--gray-300);
}

.news-card-thumb {
  width: 100%;
  height: 180px;
  background: var(--gray-100);
  position: relative;
  overflow: hidden;
}

.news-card:nth-child(1) .news-card-thumb {
  background: linear-gradient(135deg, #f3eeff, #ede9fe);
}

.news-card:nth-child(2) .news-card-thumb {
  background: linear-gradient(135deg, #fff7f0, #fff0e5);
}

.news-card:nth-child(3) .news-card-thumb {
  background: linear-gradient(135deg, #e0f2fe, #bae6fd);
}

.news-card:nth-child(4) .news-card-thumb {
  background: linear-gradient(135deg, #fdf2f8, #fce7f3);
}

.news-card-thumb-icon {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  opacity: 0.4;
}

.news-card-body {
  padding: 1.25rem;
}

.news-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  margin-bottom: 0.75rem;
}

.news-tag {
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.tag-announcements {
  background: #f3eeff;
  color: var(--purple);
}

.tag-tips {
  background: #fff0e5;
  color: var(--orange);
}

.tag-product {
  background: #e0f2fe;
  color: #0284c7;
}

.tag-safety {
  background: #dcfce7;
  color: #16a34a;
}

.news-card h3 {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--black);
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
}

.news-card-date {
  font-size: 0.8125rem;
  color: var(--gray-500);
  font-weight: 500;
}

/* Carousel scroll hints */
.news-scroll-hint {
  display: flex;
  justify-content: center;
  gap: 0.375rem;
  margin-top: 1.5rem;
}

.scroll-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all 0.3s ease;
}

.scroll-dot.active {
  background: var(--purple);
  width: 1.5rem;
  border-radius: 9999px;
}

/* ── CTA Download ── */
.cta-download {
  padding: 5rem 1.5rem;
  background: linear-gradient(180deg, var(--gray-50), var(--white));
}

.cta-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.5rem;
}

.cta-download h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.02em;
}

.cta-download p {
  font-size: 1.125rem;
  color: var(--gray-500);
  font-weight: 500;
}

.cta-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

.btn-store {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all 0.2s ease;
  letter-spacing: -0.01em;
}

.btn-appstore {
  background: var(--black);
  color: var(--white);
}

.btn-appstore:hover {
  background: var(--gray-800);
  transform: translateY(-2px);
}

.btn-googleplay {
  background: var(--white);
  color: var(--black);
  border: 2px solid var(--gray-200);
}

.btn-googleplay:hover {
  border-color: var(--black);
  transform: translateY(-2px);
}

.btn-store i {
  width: 1.25rem;
  height: 1.25rem;
}

/* ── Footer ── */
.footer {
  background: var(--gray-50);
  border-top: 1px solid var(--gray-200);
  padding: 4rem 1.5rem 2rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2.5rem 1.5rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--black);
  margin-bottom: 1rem;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-600);
  transition: color 0.15s ease;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.footer-col a:hover {
  color: var(--black);
}

.external-icon {
  display: inline-block;
  width: 0.75rem;
  height: 0.75rem;
  margin-left: 0.125rem;
  vertical-align: -1px;
  opacity: 0.4;
}

.footer-bottom {
  border-top: 1px solid var(--gray-200);
  padding-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.footer-lang {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--gray-600);
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s ease;
}

.footer-lang:hover {
  background: var(--gray-200);
}

.footer-social {
  display: flex;
  gap: 0.75rem;
}

.footer-social a {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  background: var(--gray-200);
  color: var(--gray-600);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.footer-social a:hover {
  background: var(--black);
  color: var(--white);
}

.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  color: var(--gray-500);
}

.footer-legal a {
  color: var(--gray-500);
  transition: color 0.15s ease;
}

.footer-legal a:hover {
  color: var(--black);
}

/* ── Responsive ── */
@media (min-width: 640px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .news-card {
    min-width: 340px;
  }
  .hero-visual {
    height: 350px;
  }
}

@media (min-width: 768px) {
  .section {
    padding: 6rem 2rem;
  }
  .footer {
    padding: 4rem 2rem 2rem;
  }
  .safety-content,
  .creators-content {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 1024px) {
  .nav-links {
    display: flex;
  }
  .hamburger {
    display: none;
  }
  .features-grid {
    grid-template-columns: repeat(4, 1fr);
  }
  .footer-grid {
    grid-template-columns: repeat(6, 1fr);
  }
  .hero-visual {
    height: 400px;
  }
  .news-card {
    min-width: 360px;
  }
  .footer-bottom {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

@media (min-width: 1280px) {
  .section {
    padding: 7rem 2rem;
  }
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-in {
  animation: fadeInUp 0.5s ease-out forwards;
}

.animate-delay-1 { animation-delay: 0.1s; opacity: 0; }
.animate-delay-2 { animation-delay: 0.2s; opacity: 0; }
.animate-delay-3 { animation-delay: 0.3s; opacity: 0; }
.animate-delay-4 { animation-delay: 0.4s; opacity: 0; }
</style>
