<script>
// Initialize icons
lucide.createIcons();

// ── Hamburger Menu ──
(function() {
  const btn = document.getElementById('hamburger-btn');
  const menu = document.getElementById('mobile-menu');
  const menuIcon = document.getElementById('menu-icon');
  let isOpen = false;

  function toggleMenu() {
    isOpen = !isOpen;
    menu.classList.toggle('open', isOpen);
    btn.setAttribute('aria-expanded', isOpen);
    menu.setAttribute('aria-hidden', !isOpen);

    // Swap menu icon
    menuIcon.setAttribute('data-lucide', isOpen ? 'x' : 'menu');
    lucide.createIcons({ icons: { [isOpen ? 'x' : 'menu']: menuIcon } });
    // Force re-init
    menuIcon.outerHTML = menuIcon.outerHTML;
    // Re-query and set attribute
    const newIcon = document.getElementById('menu-icon');
    if (newIcon) {
      newIcon.setAttribute('data-lucide', isOpen ? 'x' : 'menu');
    }
    lucide.createIcons();

    // Prevent body scroll when open
    document.body.style.overflow = isOpen ? 'hidden' : '';
  }

  btn.addEventListener('click', toggleMenu);

  // Close on link click
  menu.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      if (isOpen) toggleMenu();
    });
  });

  // Close on Escape
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && isOpen) toggleMenu();
  });
})();

// ── News Carousel scroll indicators ──
(function() {
  const carousel = document.getElementById('news-carousel');
  const dots = document.querySelectorAll('#scroll-dots .scroll-dot');
  const cards = carousel.querySelectorAll('.news-card');

  function updateDots() {
    const scrollLeft = carousel.scrollLeft;
    const cardWidth = cards[0] ? cards[0].offsetWidth + 20 : 360; // card width + gap
    const activeIndex = Math.round(scrollLeft / cardWidth);

    dots.forEach((dot, i) => {
      dot.classList.toggle('active', i === activeIndex);
    });
  }

  carousel.addEventListener('scroll', updateDots, { passive: true });

  // Touch / swipe support is native via overflow-x: auto + scroll-snap
  // Arrow key support for accessibility
  carousel.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowRight') {
      e.preventDefault();
      carousel.scrollBy({ left: 380, behavior: 'smooth' });
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      carousel.scrollBy({ left: -380, behavior: 'smooth' });
    }
  });

  // Update dots on resize
  window.addEventListener('resize', updateDots);
})();

// ── Scroll-triggered animations ──
(function() {
  const observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        entry.target.style.opacity = '1';
        entry.target.style.transform = 'translateY(0)';
      }
    });
  }, { threshold: 0.15 });

  document.querySelectorAll('.feature-card, .safety-stat, .news-card, .creators-icon-circle').forEach(function(el) {
    el.style.opacity = '0';
    el.style.transform = 'translateY(20px)';
    el.style.transition = 'opacity 0.5s ease-out, transform 0.5s ease-out';
    observer.observe(el);
  });
})();
</script>
</body>
